@@ -0,0 +1,139 @@
+package server
+
+import (
+	"bytes"
+	"context"
+	"encoding/csv"
+	"encoding/json"
+	"io"
+	"log/slog"
+	"net/http"
+	"os"
+	"reflect"
+	"strconv"
+	"testing"
+	"time"
+
+	"github.com/google/uuid"
+	"github.com/hkjang/ai-admin/internal/database"
+	"github.com/hkjang/ai-admin/internal/secrets"
+)
+
+// Uses a disposable database: drops schemas and must not run in parallel.
+func TestAuditExportNeutralizesControlPrefixes(t *testing.T) {
+	dsn := os.Getenv("TEST_POSTGRES_DSN")
+	if dsn == "" {
+		t.Skip("TEST_POSTGRES_DSN is not set")
+	}
+
+	ctx := context.Background()
+	db, err := database.Open(ctx, dsn)
+	if err != nil {
+		t.Fatal(err)
+	}
+	defer db.Close()
+	if _, err := db.Pool.Exec(ctx, `DROP SCHEMA IF EXISTS ai_admin CASCADE; DROP SCHEMA IF EXISTS aiportal CASCADE`); err != nil {
+		t.Fatal(err)
+	}
+	if err := db.Migrate(ctx); err != nil {
+		t.Fatal(err)
+	}
+	if err := db.Seed(ctx, "admin@example.com", "integration-password"); err != nil {
+		t.Fatal(err)
+	}
+	cipher, err := secrets.New(bytes.Repeat([]byte{7}, 32))
+	if err != nil {
+		t.Fatal(err)
+	}
+	handler := New(db, cipher, slog.New(slog.NewTextHandler(io.Discard, nil))).Handler()
+	admin := signIn(t, handler)
+
+	cases := []struct{ name, raw, want string }{
+		{"equals", "=1", "'=1"}, {"plus", "+1", "'+1"},
+		{"minus", "-1", "'-1"}, {"at", "@value", "'@value"},
+		{"tab", "\tvalue", "'\tvalue"}, {"CR", "\rvalue", "'\rvalue"},
+		{"plain", "normal 한글", "normal 한글"}, {"empty", "", ""},
+		{"apostrophe", "'=1", "'=1"}, {"quote comma newline", "a,\"b\"\nc", "a,\"b\"\nc"},
+		{"embedded controls", "a\tb\rc", "a\tb\rc"},
+	}
+	for _, tc := range cases {
+		t.Run(tc.name, func(t *testing.T) {
+			actorID := uuid.New()
+			username := actorID.String()
+			if _, err := db.Pool.Exec(ctx, `INSERT INTO ai_admin.app_user(id,username,display_name,auth_source,status)
+VALUES($1,$2,$3,'local','active')`, actorID, username, tc.raw); err != nil {
+				t.Fatal(err)
+			}
+			marker := "csv-control-regression-" + actorID.String()
+			details, err := json.Marshal(map[string]string{"stage": tc.raw, "reason": tc.raw})
+			if err != nil {
+				t.Fatal(err)
+			}
+			var id int64
+			var occurred time.Time
+			if err := db.Pool.QueryRow(ctx, `INSERT INTO ai_admin.audit_event
+(actor_user_id,actor_type,action,resource_type,resource_id,result,ip_address,request_id,details)
+VALUES($1,'user',$2,$2,$3,'success','127.0.0.1',$2,$4) RETURNING id,occurred_at`,
+				actorID, tc.raw, marker, details).Scan(&id, &occurred); err != nil {
+				t.Fatal(err)
+			}
+			response := admin.do(t, handler, http.MethodGet, "/api/v1/audit/events/export?q="+marker, nil)
+			if response.Code != http.StatusOK {
+				t.Fatalf("export status=%d body=%s", response.Code, response.Body.String())
+			}
+			if got := response.Header().Get("Content-Type"); got != "text/csv; charset=utf-8" {
+				t.Fatalf("Content-Type=%q", got)
+			}
+			bom := []byte{0xef, 0xbb, 0xbf}
+			if !bytes.HasPrefix(response.Body.Bytes(), bom) {
+				t.Fatal("missing UTF-8 BOM")
+			}
+			records, err := csv.NewReader(bytes.NewReader(response.Body.Bytes()[len(bom):])).ReadAll()
+			if err != nil {
+				t.Fatal(err)
+			}
+			header := []string{"id", "occurred_at", "actor_username", "actor_name", "actor_type", "action", "resource_type", "resource_id", "result", "ip_address", "request_id", "stage", "failure_reason"}
+			want := [][]string{header, {strconv.FormatInt(id, 10), occurred.UTC().Format(time.RFC3339Nano), username, tc.want, "user", tc.want, tc.want, marker, "success", "127.0.0.1/32", tc.want, tc.want, tc.want}}
+			if !reflect.DeepEqual(records, want) {
+				t.Errorf("CSV=%q want=%q", records, want)
+			}
+
+			// Export escaping must not leak back into storage or the JSON API.
+			var name, action, resourceType, requestID, stage, reason string
+			if err := db.Pool.QueryRow(ctx, `SELECT u.display_name,e.action,e.resource_type,e.request_id,e.details->>'stage',e.details->>'reason'
+FROM ai_admin.audit_event e JOIN ai_admin.app_user u ON u.id=e.actor_user_id WHERE e.id=$1`, id).Scan(&name, &action, &resourceType, &requestID, &stage, &reason); err != nil {
+				t.Fatal(err)
+			}
+			for _, got := range []string{name, action, resourceType, requestID, stage, reason} {
+				if got != tc.raw {
+					t.Errorf("stored value=%q want=%q", got, tc.raw)
+				}
+			}
+			listed := admin.do(t, handler, http.MethodGet, "/api/v1/audit/events?q="+marker, nil)
+			if listed.Code != http.StatusOK {
+				t.Fatalf("JSON status=%d", listed.Code)
+			}
+			var page struct{ Data []auditEvent }
+			if err := json.Unmarshal(listed.Body.Bytes(), &page); err != nil {
+				t.Fatal(err)
+			}
+			if len(page.Data) != 1 {
+				t.Fatalf("JSON rows=%d", len(page.Data))
+			}
+			item := page.Data[0]
+			if item.ID != id || item.ResourceType == nil || item.RequestID == nil {
+				t.Fatalf("unexpected JSON event: %+v", item)
+			}
+			for _, got := range []string{item.ActorName, item.Action, *item.ResourceType, *item.RequestID, item.Stage, item.FailureReason} {
+				if got != tc.raw {
+					t.Errorf("JSON value=%q want=%q", got, tc.raw)
+				}
+			}
+			for _, key := range []string{"stage", "reason"} {
+				if item.Details[key] != tc.raw {
+					t.Errorf("JSON details[%s]=%q want=%q", key, item.Details[key], tc.raw)
+				}
+			}
+		})
+	}
+}
